import { useServiceRequest } from '@pasarpolis/common-react-hooks'

import { useWalletContextValue } from '../../context'
import { Wallet } from '../actions'

export const useWalletServiceCall = (actionsCall = () => {}) => {
  const [walletState, dispatch] = useWalletContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }

  return [walletState, request]
}

export const useGetWalletList = () => {
  return useWalletServiceCall(Wallet.getWalletList)
}

export const useGetMasterList = () => {
  return useWalletServiceCall(Wallet.getMasterList)
}

export const useGetWalletTransaction = () => {
  return useWalletServiceCall(Wallet.getWalletTransaction)
}

export const useGetWalletSummary = () => {
  return useWalletServiceCall(Wallet.getWalletSummary)
}

export const useAddWallet = () => {
  return useWalletServiceCall(Wallet.addWallet)
}

export const useAddTopUp = () => {
  return useWalletServiceCall(Wallet.addTopUp)
}

export const useDebitTopUp = () => {
  return useWalletServiceCall(Wallet.debitTopUp)
}

export const useEditWallet = () => {
  return useWalletServiceCall(Wallet.editWallet)
}

export const useResetState = () => {
  const [, dispatch] = useWalletContextValue()
  const resetState = (keys = []) => {
    dispatch(Wallet.resetReduxStateWallet(keys))
  }
  return [resetState]
}
