/* eslint-disable react-hooks/exhaustive-deps */
import { useCallback, useState } from "react"
import { Modal, Form, Button, Input ,Checkbox} from 'antd'
import WalletModalWrapper from '../style'
import { imageUrl } from '../../constant'
import { showNotification } from "../../../../../components/ShowNotification" 

const { CloseIcon } = imageUrl

const AddTopUpModal = ({
  isOpen,
  closeModal,
  form,
  ADD_TOP_UP_LOADER,
  DEBIT_TOP_UP_LOADER,
  addTopUpRequest,
  debitTopUpRequest,
  walletId,
  balance
}) => {
  const {getFieldDecorator} = form

  const validateForm = useCallback(async () => {
    return new Promise((resolve) => {
      form.validateFields((error) => {
        resolve(!error)
      })
    })
  }, [form])

  const handleSubmit = useCallback(async (e) => {
    e.preventDefault()
    const valid = await validateForm()
    if (!valid) return
    const formValues = {
      ...form.getFieldsValue()
    }
    const debit=formValues.debit
    delete formValues.debit
    const amount = +formValues.amount
    if(!debit){
      addTopUpRequest({
        body: {...formValues, amount: +formValues.amount, wallet_id: walletId}
      })
    }else{
      if( amount > +balance ) {
        showNotification('error', 'Please provide valid amount')
      }else {
        debitTopUpRequest({
          body: {...formValues, amount: +formValues.amount, wallet_id: walletId}
        })
      }
      
    }
  }, [validateForm, form, addTopUpRequest, debitTopUpRequest])

  return (
    <Modal
      title=""
      visible={isOpen}
      footer={null}
      closable={false}
      onCancel={closeModal}
      bodyStyle={{padding: 0}}
      afterClose={() => form.resetFields()}
    >
      <WalletModalWrapper>
        <div className="title">
          <strong>Topup Wallet</strong>
          <img
            onClick={closeModal}
            src={CloseIcon}
            className="close-icon"
            alt="close"
          />
        </div>
        <Form onSubmit={handleSubmit}>
          <label>Transaction ID</label>
          <Form.Item>
            {getFieldDecorator("reference_id", {
              rules: [
                {required: true, message: "Transaction ID can not be empty"}
              ]
            })(<Input placeholder="Transaction ID" />)}
          </Form.Item>
          <label>Topup Amount (Rp)</label>
          <Form.Item>
            {getFieldDecorator("amount", {
              rules: [
                {required: true, message: "Topup Amount can not be empty"},
                {pattern: /^\d*\.?\d*$/, message: "Amount should be numeric"}
              ]
            })(<Input placeholder="Topup Amount" />)}
          </Form.Item>
          <label>Remark</label>
          <Form.Item>
            {getFieldDecorator("remarks", {
              rules: [
                {required: true, message: "Remark can not be empty"}
              ]})(
              <Input.TextArea placeholder="Remark" />
            )}
          </Form.Item>
          <Form.Item>
            {getFieldDecorator("debit", {
              rules: [
                {required: false}
              ]})(
                <Checkbox>
                Debit
              </Checkbox>
            )}
          </Form.Item>
          <Button
            key="submit"
            type="primary"
            htmlType="submit"
            loading={!!ADD_TOP_UP_LOADER || !!DEBIT_TOP_UP_LOADER}
            className="form-submit"
          >
            Submit
          </Button>
        </Form>
      </WalletModalWrapper>
    </Modal>
  )
}

const WrappedForm = Form.create({})(AddTopUpModal)

export default WrappedForm
