/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect, useMemo, useCallback } from 'react'
import { Form, Row, Icon, Tag, Divider, notification, Spin } from 'antd'
import QueryString from 'query-string'
import moment from 'moment-timezone'
import { get } from 'lodash/object'
import {
  useLoaderContextValue,
  useErrorContextValue,
  resetError
} from '@pasarpolis/common-react-hooks'
import EditWalletModal from './../../component/editWalletModal'
import { WalletDetailFilterKeyMap, imageUrl, currencyChange } from '../../constant'
import AddTopUpModal from '../../component/addTopUpModal'
import PermissionCheckerV2 from '../../../../../components/permissionCheckerV2'
import {
  DateRangeFilter,
  FilterInput
} from '../../../../../components/tables/helperCells'
import LayoutContentWrapper from '../../../../../components/utility/layoutWrapper'
import TableWrapper from '../../pagination.style'
import WalletDetailWrapper from './style'
import QuerySearchBuilder from '../../../../../helpers/querySearchBuilder'
import {
  useGetWalletTransaction,
  useGetWalletSummary,
  useAddTopUp,
  useGetMasterList,
  useResetState,
  useEditWallet,
  useDebitTopUp
} from '../../state/hooks/useWalletContext'

const {
  FilteredIcon,
  PartnerIcon,
  ProductIcon,
  ProviderIcon,
  PackageIcon,
  BackIcon,
  MoneyBagIcon,
  BalanceIcon
} = imageUrl

const WalletDetail = ({ location, history, match }) => {
  const [filterActive, setFilterActive] = useState(false)
  const [searchTextQuery, setSearchTextQuery] = useState({})
  const [appliedFilter, setAppliedFilter] = useState({})
  const [isTopUpModalVisible, showAddTopUpModal] = useState(false)
  const [isEditModalVisible, showEditModal] = useState(false)
  const [{ getWalletTransactionData = {} }, getWalletTransactionRequest] = useGetWalletTransaction()
  const [{ getMasterListData = {} }, getMasterListRequest] = useGetMasterList()
  const [{ getWalletSummaryData = {} }, getWalletSummaryRequest] = useGetWalletSummary()
  const [, addTopUpRequest] = useAddTopUp()
  const [, editWalletRequest] = useEditWallet()
  const [, debitTopUpRequest] = useDebitTopUp()
  const summaryData = useMemo(() => {
    return (
      getWalletSummaryData?.data &&
      Array.isArray(getWalletSummaryData?.data) &&
      getWalletSummaryData?.data[0]
    )
  }, [getWalletSummaryData])

  const [resetState] = useResetState()
  const [
    {
      ADD_TOP_UP_LOADER,
      DEBIT_TOP_UP_LOADER,
      GET_WALLET_TRANSACTION_LOADER,
      GET_WALLET_SUMMARY_LOADER,
      GET_MASTER_LIST_LOADER
    }
  ] = useLoaderContextValue()

  const [error, dispatchError] = useErrorContextValue()

  const {
    GET_WALLET_TRANSACTION_ERROR = '',
    GET_WALLET_SUMMARY_ERROR = '',
    ADD_TOP_UP_ERROR = '',
    DEBIT_TOP_UP_ERROR = '',
    EDIT_WALLET_ERROR = '',
    getWalletTransactionStatus,
    getWalletSummaryStatus,
    addTopUpStatus,
    addTopUpErrorData,
    debitTopUpStatus,
    debitTopUpErrorData,
    editWalletStatus = '',
    editWalletErrorData = ''
  } = error

  useEffect(() => {
    const querySearch = QueryString.parse(location?.search)
    fetch(querySearch)
    getWalletSummaryRequest({
      query: {
        wallet_id: get(match, 'params.id')
      }
    })
    getMasterListRequest()
    if (querySearch.sort) {
      delete querySearch.sort
    }
    setSearchTextQuery({ ...querySearch })
    setAppliedFilter({ ...querySearch })
    return () => resetState(['getWalletTransactionData', 'getWalletSummaryData'])
  }, [])

  // Error handling notify error status
  useEffect(() => {
    if (GET_WALLET_TRANSACTION_ERROR) {
      getWalletTransactionStatus && notification.error({ message: getWalletTransactionStatus })
      dispatchError(
        resetError({
          GET_WALLET_TRANSACTION_ERROR: false,
          getWalletTransactionStatus: ''
        })
      )
    } else if (GET_WALLET_SUMMARY_ERROR) {
      getWalletSummaryStatus && notification.error({ message: getWalletSummaryStatus })
      dispatchError(
        resetError({
          GET_WALLET_SUMMARY_ERROR: false,
          getWalletSummaryStatus: ''
        })
      )
    } else if (ADD_TOP_UP_ERROR) {
      if (
        addTopUpErrorData?.errors &&
        addTopUpErrorData?.errors.length &&
        addTopUpErrorData?.errors[0]?.message
      ) {
        addTopUpErrorData?.errors[0]?.message &&
          notification.error({ message: addTopUpErrorData?.errors[0]?.message })
      } else {
        addTopUpStatus && notification.error({ message: addTopUpStatus })
      }
      dispatchError(
        resetError({
          ADD_TOP_UP_ERROR: false,
          addTopUpStatus: '',
          addTopUpErrorData: ''
        })
      )
    } else if (!ADD_TOP_UP_ERROR && addTopUpStatus === 'success') {
      addTopUpStatus && notification.success({ message: addTopUpStatus })
      showAddTopUpModal(false)
      const querySearch = QueryString.parse(location?.search)
      fetch(querySearch)
      getWalletSummaryRequest({
        query: {
          wallet_id: get(match, 'params.id')
        }
      })
      showAddTopUpModal(false)
      dispatchError(
        resetError({
          addTopUpStatus: ''
        })
      )
    }else if (DEBIT_TOP_UP_ERROR) {
      if (
        debitTopUpErrorData?.errors &&
        debitTopUpErrorData?.errors.length &&
        debitTopUpErrorData?.errors[0]?.message
      ) {
        debitTopUpErrorData?.errors[0]?.message &&
          notification.error({ message: debitTopUpErrorData?.errors[0]?.message })
      } else {
        debitTopUpStatus && notification.error({ message: debitTopUpStatus })
      }
      dispatchError(
        resetError({
          DEBIT_TOP_UP_ERROR: false,
          debitTopUpStatus: '',
          debitTopUpErrorData: ''
        })
      )
    } else if (!DEBIT_TOP_UP_ERROR && debitTopUpStatus === 'success') {
      debitTopUpStatus && notification.success({ message: debitTopUpStatus })
      showAddTopUpModal(false)
      const querySearch = QueryString.parse(location?.search)
      fetch(querySearch)
      getWalletSummaryRequest({
        query: {
          wallet_id: get(match, 'params.id')
        }
      })
      showAddTopUpModal(false)
      dispatchError(
        resetError({
          debitTopUpStatus: ''
        })
      )
    }

    if (EDIT_WALLET_ERROR) {
      if (
        editWalletErrorData &&
        editWalletErrorData?.errors.length &&
        editWalletErrorData?.errors[0]?.message
      ) {
        editWalletErrorData?.errors[0]?.message &&
          notification.error({
            message: editWalletErrorData?.errors[0]?.message
          })
      } else {
        editWalletStatus && notification.error({ message: editWalletStatus })
      }
      const querySearch = QueryString.parse(location?.search)
      fetch(querySearch)
      getWalletSummaryRequest({
        query: {
          wallet_id: get(match, 'params.id')
        }
      })
      dispatchError(
        resetError({
          EDIT_WALLET_ERROR: false,
          editWalletStatus: '',
          editWalletErrorData: ''
        })
      )
      showEditModal(false)
    } else if (!EDIT_WALLET_ERROR && editWalletStatus === 'success') {
      editWalletStatus && notification.success({ message: editWalletStatus })
      showEditModal(false)
      const querySearch = QueryString.parse(location?.search)
      fetch(querySearch)
      getWalletSummaryRequest({
        query: {
          wallet_id: get(match, 'params.id')
        }
      })
      showEditModal(false)
      dispatchError(
        resetError({
          editWalletStatus: ''
        })
      )
    }
  }, [
    GET_WALLET_TRANSACTION_ERROR,
    GET_WALLET_SUMMARY_ERROR,
    ADD_TOP_UP_ERROR,
    DEBIT_TOP_UP_ERROR,
    EDIT_WALLET_ERROR,
    getWalletTransactionStatus,
    getWalletSummaryStatus,
    addTopUpStatus,
    addTopUpErrorData,
    debitTopUpStatus,
    debitTopUpErrorData,
    editWalletStatus,
    editWalletErrorData
  ])

  const renderTitle = useCallback((titleClass, text) => {
    return (
      <div className={titleClass}>
        <span>{text}</span>
      </div>
    )
  }, [])

  const onInputChange = useCallback(
    (value, identifier) => {
      setSearchTextQuery({
        ...searchTextQuery,
        [identifier]: identifier === 'reference_id' ? [value] : value?.trim()
      })
    },
    [searchTextQuery]
  )

  const onSearch = useCallback(
    (e, key) => {
      e.preventDefault()
      const searchText = { ...searchTextQuery, page: 1 }
      const search = QuerySearchBuilder(searchText)
      history.push({ pathname: location?.pathname, search })
      fetch(searchText)
      setFilterActive({ ...filterActive, [key]: false })
      setAppliedFilter(searchTextQuery)
    },
    [searchTextQuery]
  )

  const onSearchDate = useCallback(
    (e, key) => {
      const { startDate, endDate } = e
      const date = {
        from_date: `${startDate} 00:00:00`,
        to_date: `${endDate} 23:59:59`
      }
      setSearchTextQuery({ ...searchTextQuery, ...date })
      const searchText = { ...searchTextQuery, ...date, page: 1 }
      const search = QuerySearchBuilder(searchText)
      history.push({ pathname: location?.pathname, search })
      fetch(searchText)
      setFilterActive({ ...filterActive, [key]: false })
      setAppliedFilter(searchText)
    },
    [searchTextQuery, filterActive, location]
  )

  const renderIcon = useCallback(() => {
    return (
      <div className='filter-icon-wrapper'>
        <img src={FilteredIcon} className='filter-icon' alt='' />
      </div>
    )
  }, [])

  const columns = [
    {
      key: 'reference_id',
      title: renderTitle('title-with-margin', 'Transaction ID'),
      dataIndex: 'reference_id',
      filterDropdown: (
        <FilterInput
          idIdentifier='reference_id'
          searchText={
            searchTextQuery.reference_id
              ? searchTextQuery.reference_id
              : undefined
          }
          onInputChange={(e) => onInputChange(e.target.value, 'reference_id')}
          onSearch={(e) => onSearch(e, 'reference_id')}
        />
      ),
      filterIcon: renderIcon(false),
      filterDropdownVisible: filterActive?.reference_id,
      onFilterDropdownVisibleChange: (visible) =>
        setFilterActive({ ...filterActive, reference_id: visible }),
      sorter: true,
      sortDirections: ['descend', 'ascend']
    },
    {
      key: 'created_at',
      title: renderTitle('title-with-margin', 'Topup Date'),
      dataIndex: 'created_at',
      render: (date) => moment(date).tz('Asia/Jakarta').format('lll'),
      filterDropdown: (
        <DateRangeFilter
          idIdentifier='created_at'
          onInputChange={(e) => onInputChange(e.target.value, 'created_at')}
          onSearch={(e) => onSearchDate(e, 'created_at')}
          startDate={searchTextQuery.from_date}
          endDate={searchTextQuery.to_date}
        />
      ),
      filterIcon: renderIcon(),
      filterDropdownVisible: filterActive?.created_at,
      onFilterDropdownVisibleChange: (visible) => setFilterActive({ ...filterActive, created_at: visible })
    },
    {
      key: 'user_email',
      title: renderTitle('title-with-margin', 'Topup By'),
      dataIndex: 'user_email',
      filterDropdown: (
        <FilterInput
          idIdentifier='user_email'
          searchText={
            searchTextQuery.user_email ? searchTextQuery.user_email : undefined
          }
          onInputChange={(e) => onInputChange(e.target.value, 'user_email')}
          onSearch={(e) => onSearch(e, 'user_email')}
        />
      ),
      filterIcon: renderIcon(),
      filterDropdownVisible: filterActive?.user_email,
      onFilterDropdownVisibleChange: (visible) =>
        setFilterActive({ ...filterActive, user_email: visible })
    },
    {
      key: 'amount',
      title: renderTitle('title-without-margin', 'Topup Amount (Rp)'),
      dataIndex: 'amount',
      render: (amount) => currencyChange(amount)
    },
    {
      key: 'remarks',
      title: renderTitle('title-without-margin', 'Remark'),
      dataIndex: 'remarks'
    }
  ]

  const clearQuerySearchBuilder = useCallback(
    (identifier) => {
      const oldSearch = QueryString.parse(location?.search)
      delete oldSearch[identifier]
      const search = QuerySearchBuilder(oldSearch)
      history.push({ pathname: location?.pathname, search })
      return oldSearch
    },
    [location]
  )

  const clearFilter = useCallback(
    (identifier) => {
      setSearchTextQuery({
        ...searchTextQuery,
        [identifier]: undefined
      })
      setAppliedFilter({
        ...appliedFilter,
        [identifier]: undefined
      })

      const oldSearch = clearQuerySearchBuilder(identifier)
      fetch(oldSearch)
    },
    [
      searchTextQuery,
      clearQuerySearchBuilder,
      setAppliedFilter,
      setSearchTextQuery
    ]
  )

  const fetch = useCallback(
    (params = {}) => {
      const { page } = params
      const pageNumber = Number(page) || 1
      delete params.page
      getWalletTransactionRequest({
        query: {
          ...params,
          page_number: pageNumber,
          action: 'credit,debit',
          wallet_id: get(match, 'params.id')
        }
      })
    },
    [getWalletTransactionRequest]
  )

  const handlePageChange = useCallback(
    (pagination, filters, sorter) => {
      const { current } = pagination
      const querySearch = QueryString.parse(location?.search)
      const searchText = { ...querySearch, page: current }
      if (sorter?.field === 'reference_id' && sorter?.order === 'descend') {
        searchText.sort = 'desc'
      } else if (sorter?.field === 'reference_id' && sorter?.order === 'ascend') {
        searchText.sort = 'asc'
      } else {
        searchText.sort = undefined
      }

      const search = QuerySearchBuilder(searchText)
      history.push({ pathname: location?.pathname, search })
      fetch(searchText)
    },
    [QueryString, location]
  )

  const moveToAsoWalletPage = () => {
    history.replace('/deposit/aso-wallet')
  }

  const DetailComponent = ({ icon, name = '', value = '' }) => {
    return (
      <div className='margin'>
        <div>
          <img src={icon} className='detail-icon' alt='' />
        </div>
        <div className='detail'>
          <span className='detail-name'>{name}</span>
          <span className='detail-value'>{value}</span>
        </div>
      </div>
    )
  }

  const handleEditBtn = (partnerCode, productCode) => {
    showEditModal(true)

    getMasterListRequest({
      query: {
        partnerCode: partnerCode,
        productCode: productCode
      }
    })
  }

  return (
    <LayoutContentWrapper className='referral-table'>
      <WalletDetailWrapper>
        <Spin
          spinning={GET_WALLET_TRANSACTION_LOADER || GET_WALLET_SUMMARY_LOADER}
        >
          <Row type='flex' align='middle'>
            <img
              src={BackIcon}
              className='back-icon'
              onClick={moveToAsoWalletPage}
              alt=''
            />
            <h3>
              <b>Wallet Detail</b>
            </h3>
          </Row>
          <Divider />
          <div className='card'>
            <DetailComponent
              icon={PartnerIcon}
              name='Partner'
              value={summaryData?.partner_name || summaryData?.partner_code}
            />
            <DetailComponent
              icon={ProviderIcon}
              name='Provider'
              value={summaryData?.provider_name || summaryData?.provider_code}
            />
            <DetailComponent
              icon={ProductIcon}
              name='Product'
              value={summaryData?.product_name || summaryData?.product_code}
            />
            <DetailComponent
              icon={PackageIcon}
              name='Package'
              value={summaryData?.package_code_list}
            />
            <div className='edit-detail'>
              <div
                onClick={() =>
                  handleEditBtn(
                    summaryData?.partner_code,
                    summaryData?.product_code
                  )}
              >
                <strong>Edit Package</strong>
              </div>
            </div>
            <div className='topup-detail-wrapper'>
              <div className='display'>
                <img src={BalanceIcon} className='detail-icon' alt='' />
                <div className='detail'>
                  <span className='detail-name balance-value'>Balance</span>
                  <span className='balance-value'>
                    Rp {currencyChange(summaryData?.total_balance)}
                  </span>
                </div>
              </div>
              <PermissionCheckerV2 requiredPermission='ops.aso_wallet_topup'>
                <div
                  className='wallet-wrapper'
                  onClick={() => showAddTopUpModal(true)}
                >
                  <strong className='wallet-text'>Topup</strong>
                  <img src={MoneyBagIcon} className='wallet-icon' alt='' />
                </div>
              </PermissionCheckerV2>
            </div>
          </div>
          {appliedFilter &&
            Object.keys(appliedFilter).map((key, index) => {
              if (appliedFilter[key]) {
                return (
                  <Tag key={index} className='filter-tag' color='volcano'>
                    {WalletDetailFilterKeyMap[key]} - {appliedFilter[key]}
                    <span
                      className='remove-filter'
                      onClick={(e) => clearFilter(key)}
                    >
                      <Icon type='close' className='close' />
                    </span>
                  </Tag>
                )
              } else {
                return ' '
              }
            })}
          <TableWrapper
            columns={columns}
            rowKey={(record) => record.reference_id}
            dataSource={getWalletTransactionData.data}
            pagination={{
              pageSize: 10,
              total: Number(getWalletTransactionData?.metadata?.total_count),
              current: getWalletTransactionData?.metadata?.page_number
            }}
            onChange={handlePageChange}
            className='isoSearchableTable'
          />
          <AddTopUpModal
            closeModal={() => showAddTopUpModal(false)}
            isOpen={isTopUpModalVisible}
            ADD_TOP_UP_LOADER={ADD_TOP_UP_LOADER}
            DEBIT_TOP_UP_LOADER={DEBIT_TOP_UP_LOADER}
            addTopUpRequest={addTopUpRequest}
            debitTopUpRequest={debitTopUpRequest} 
            walletId={get(match, 'params.id')}
            balance = {summaryData?.total_balance}
          />

          <EditWalletModal
            closeModal={() => showEditModal(false)}
            visible={isEditModalVisible}
            getMasterListData={getMasterListData}
            getWalletSummaryData={summaryData}
            editWalletRequest={editWalletRequest}
            getMasterListRequest={getMasterListRequest}
            loader={GET_MASTER_LIST_LOADER}
          />
        </Spin>
      </WalletDetailWrapper>
    </LayoutContentWrapper>
  )
}

export default Form.create({})(WalletDetail)
