import urls from '../../../../config/urls'
const configUrl = urls.url

export const Wallet = {
  GET_WALLET_LIST: 'GET_WALLET_LIST',
  GET_WALLET_LIST_REQUEST: 'GET_WALLET_LIST_REQUEST',

  GET_MASTER_LIST: 'GET_MASTER_LIST',
  GET_MASTER_LIST_REQUEST: 'GET_MASTER_LIST_REQUEST',

  GET_WALLET_SUMMARY: 'GET_WALLET_SUMMARY',
  GET_WALLET_SUMMARY_REQUEST: 'GET_WALLET_SUMMARY_REQUEST',

  ADD_WALLET: 'ADD_WALLET',
  ADD_WALLET_REQUEST: 'ADD_WALLET_REQUEST',

  GET_WALLET_TRANSACTION: 'GET_WALLET_TRANSACTION',
  GET_WALLET_TRANSACTION_REQUEST: 'GET_WALLET_TRANSACTION_REQUEST',

  ADD_TOP_UP: 'ADD_TOP_UP',
  ADD_TOP_UP_REQUEST: 'ADD_TOP_UP_REQUEST',

  DEBIT_TOP_UP: 'DEBIT_TOP_UP',
  DEBIT_TOP_UP_REQUEST: 'DEBIT_TOP_UP_REQUEST',

  EDIT_WALLET: 'EDIT_WALLET',
  EDIT_WALLET_REQUEST: 'EDIT_WALLET_REQUEST',

  RESET_REDUX_STATE_WALLET: 'RESET_REDUX_STATE_WALLET',

  getWalletList: payload => ({
    type: Wallet.GET_WALLET_LIST_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.getWalletListUrl
    }
  }),
  getMasterList: payload => ({
    type: Wallet.GET_MASTER_LIST_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.getMasterListUrl
    }
  }),
  getWalletSummary: payload => ({
    type: Wallet.GET_WALLET_SUMMARY_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.getWalletSummaryUrl
    }
  }),
  getWalletTransaction: payload => ({
    type: Wallet.GET_WALLET_TRANSACTION_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: configUrl.getWalletTransactionUrl
    }
  }),
  addWallet: payload => ({
    type: Wallet.ADD_WALLET_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.addWalletUrl
    }
  }),
  addTopUp: payload => ({
    type: Wallet.ADD_TOP_UP_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.addTopUpUrl
    }
  }),
  debitTopUp: payload => ({
    type: Wallet.DEBIT_TOP_UP_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.debitTopUpUrl
    }
  }),
  editWallet: payload => ({
    type: Wallet.EDIT_WALLET_REQUEST,
    payload: {
      ...payload,
      method: 'post',
      url: configUrl.editWalletUrl
    }
  }),
  resetReduxStateWallet: keys => ({
    type: Wallet.RESET_REDUX_STATE_WALLET,
    payload: keys
  })
}
