/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect, useCallback } from 'react'
import { Form, Modal, Button, Checkbox } from 'antd'
import WalletModalWrapper from './../style'
import { imageUrl } from '../../constant'
const { CloseIcon } = imageUrl

const EditWalletModal = ({
  closeModal,
  visible,
  getMasterListData,
  getWalletSummaryData,
  form,
  editWalletRequest,
  loader
}) => {
  const { getFieldDecorator } = form

  const [initialDict, setInitialDict] = useState({})

  useEffect(() => {
    form.resetFields()
    const temp = getWalletSummaryData?.package_code_list.split(',')
    const dict = {}
    if (temp && Array.isArray(temp)) {
      temp.forEach((val) => {
        dict[val] = true
        return dict
      })
    }

    setInitialDict(dict)
  }, [getWalletSummaryData, getMasterListData])

  const validateForm = useCallback(async () => {
    return new Promise((resolve) => {
      form.validateFields((error) => {
        resolve(!error)
      })
    })
  }, [form])

  const handleSubmit = useCallback(
    async (e) => {
      e.preventDefault()
      const valid = await validateForm()
      if (!valid) {
        return
      }
      const formValues = form.getFieldsValue()
      const packageCode = []
      Object.keys(formValues).forEach((pack) => {
        if (formValues[pack]) {
          packageCode.push(pack)
        }
      })

      const reqObj = {
        wallet_id: getWalletSummaryData?.wallet_id,
        partner_code: getWalletSummaryData?.partner_code,
        product_code: getWalletSummaryData?.product_code,
        provider_code: getWalletSummaryData?.provider_code,
        package_code_list: packageCode
      }

      editWalletRequest({
        body: reqObj
      })
    },
    [validateForm, form, editWalletRequest]
  )

  return (
    <Modal
      title=''
      visible={visible}
      footer={null}
      closable={false}
      onCancel={closeModal}
      bodyStyle={{ padding: 0 }}
    >
      <WalletModalWrapper>
        <div className='title'>
          <strong>Edit Wallet</strong>
          <img
            onClick={closeModal}
            src={CloseIcon}
            className='close-icon'
            alt='close'
          />
        </div>

        <div className='editWallet__content'>
          <h1 className='heading'> Select Packages </h1>
          <div className='form-container'>
            <p className='container1'>
              {getWalletSummaryData?.package_code_list}
            </p>
            <div className='form-content'>
              <Form onSubmit={handleSubmit}>
                {getMasterListData?.package_code_list?.map(
                  (packageList, key) => (
                    <Form.Item key={key} className='edit-form-item'>
                      {getFieldDecorator(packageList, {
                        initialValue: !!initialDict[packageList],
                        valuePropName: 'checked'
                      })(<Checkbox>{packageList}</Checkbox>)}
                    </Form.Item>
                  )
                )}
              </Form>
            </div>
          </div>
        </div>
        <Button
          key='submit'
          type='primary'
          htmlType='submit'
          className='form-submit'
          loading={loader}
          onClick={handleSubmit}
        >
          Submit
        </Button>
      </WalletModalWrapper>
    </Modal>
  )
}

export default Form.create({})(EditWalletModal)
